/** Standard accessible library UI; metadata and artwork are read off the UI thread. */
public class LibraryActivity extends Activity {
 android.content.SharedPreferences prefs;EditText search;TextView count,empty;ListView list;TrackAdapter adapter;int category,accent;List<LibraryStore.Track> visible=new ArrayList<>();LinearLayout chips;final Map<String,Meta> metadata=new LinkedHashMap<String,Meta>(64,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,Meta> entry){return size()>64;}};final Set<String> pending=new HashSet<>();final ExecutorService worker=Executors.newFixedThreadPool(2);volatile boolean closed;
 static final class Meta {Bitmap art;String artist="";long duration;}
 protected void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("noir",0);int[] palette={Color.WHITE,0xffff343b,0xffffd43b,0xff269bff,0xffbf59ff,0xffff343b,0xff269bff};accent=palette[Math.max(0,Math.min(6,prefs.getInt("theme",5)))];
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.BLACK);SafeArea.install(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=button("‹","Back to player");back.setTextSize(28);back.setBackgroundColor(Color.TRANSPARENT);back.setOnClickListener(v->finish());header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(56)));TextView title=text("Your library",26,Color.WHITE);title.setTypeface(null,Typeface.BOLD);header.addView(title,new LinearLayout.LayoutParams(0,-1,1));Button add=button("+","Import audio and video files");add.setTextSize(28);add.setBackgroundColor(Color.TRANSPARENT);add.setOnClickListener(v->importFiles());header.addView(add,new LinearLayout.LayoutParams(dp(56),dp(56)));root.addView(header);
  search=new EditText(this);search.setHint("Search your songs and videos");search.setSingleLine(true);search.setTextColor(Color.WHITE);search.setHintTextColor(0xff999999);search.setTextSize(16);search.setPadding(dp(16),0,dp(16),0);search.setBackground(round(0xff151515,12));LinearLayout.LayoutParams field=new LinearLayout.LayoutParams(-1,dp(48));field.setMargins(dp(16),dp(12),dp(16),dp(12));root.addView(search,field);
  HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);chips=new LinearLayout(this);chips.setPadding(dp(16),0,dp(12),0);String[] labels={"All","Audio","Video","Downloads"};for(int i=0;i<labels.length;i++){final int value=i;Button chip=button(labels[i],labels[i]+" filter");chip.setTextSize(14);chip.setOnClickListener(v->{category=value;refresh();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,dp(44));p.setMargins(0,0,dp(8),0);chips.addView(chip,p);}scroll.addView(chips);root.addView(scroll);
  count=text("",13,0xff999999);count.setPadding(dp(20),dp(12),dp(16),dp(8));root.addView(count);
  FrameLayout body=new FrameLayout(this);list=new ListView(this);list.setDividerHeight(dp(1));list.setDivider(new android.graphics.drawable.ColorDrawable(0xff202020));list.setClipToPadding(false);list.setPadding(0,0,0,dp(12));adapter=new TrackAdapter();list.setAdapter(adapter);list.setOnItemClickListener((parent,view,pos,id)->select(visible.get(pos)));body.addView(list,new FrameLayout.LayoutParams(-1,-1));empty=text("",17,0xffbbbbbb);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(32),0,dp(32),0);body.addView(empty,new FrameLayout.LayoutParams(-1,-1));root.addView(body,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int c){refresh();}public void afterTextChanged(Editable e){}});refresh();if(getIntent().getBooleanExtra("import",false)&&state==null)importFiles();
 }
 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
 Button button(String value,String description){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setContentDescription(description);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(16),0,dp(16),0);b.setBackground(round(0xff161616,20));return b;}
 GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 void refresh(){visible=LibraryStore.filter(LibraryStore.read(prefs),search.getText().toString(),category);count.setText(visible.size()+" items • Imported files and downloads");for(int i=0;i<chips.getChildCount();i++){Button b=(Button)chips.getChildAt(i);b.setTextColor(i==category?Color.BLACK:Color.WHITE);b.setBackground(round(i==category?accent:0xff171717,20));}adapter.notifyDataSetChanged();boolean none=visible.isEmpty();empty.setVisibility(none?View.VISIBLE:View.GONE);list.setVisibility(none?View.GONE:View.VISIBLE);empty.setText(LibraryStore.read(prefs).isEmpty()?"Your library starts here\n\nTap + to import audio or video files.":"No matching files\n\nTry another search or filter.");}
 void select(LibraryStore.Track track){setResult(RESULT_OK,new Intent().putExtra("uri",track.uri).putExtra("title",track.title));finish();}
 void importFiles(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*"}).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(intent,11);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=11||result!=RESULT_OK||data==null)return;List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());for(Uri uri:uris){if(!"content".equals(uri.getScheme()))continue;try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}String name="Imported media";try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())name=cursor.getString(0);}catch(RuntimeException ignored){}String mime="";try{mime=getContentResolver().getType(uri);}catch(RuntimeException ignored){}LibraryStore.add(prefs,new LibraryStore.Track(uri.toString(),name,mime));}refresh();}
 void menu(View anchor,LibraryStore.Track track){PopupMenu menu=new PopupMenu(this,anchor);menu.getMenu().add("Play");menu.getMenu().add("Remove from library");menu.setOnMenuItemClickListener(item->{if(item.getTitle().equals("Play"))select(track);else new AlertDialog.Builder(this).setTitle("Remove from library?").setMessage("The original file will remain on your device.").setPositiveButton("Remove",(d,w)->{LibraryStore.remove(prefs,track.uri);refresh();}).setNegativeButton("Cancel",null).show();return true;});menu.show();}
 class Holder {ImageView cover;TextView title,subtitle;Button more;String uri;}
 class TrackAdapter extends BaseAdapter {
  public int getCount(){return visible.size();}public Object getItem(int p){return visible.get(p);}public long getItemId(int p){return visible.get(p).uri.hashCode();}
  public View getView(int position,View reused,ViewGroup parent){Holder h;LinearLayout row;if(reused==null){h=new Holder();row=new LinearLayout(LibraryActivity.this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(16),dp(12),dp(8),dp(12));row.setMinimumHeight(dp(80));h.cover=new ImageView(LibraryActivity.this);h.cover.setScaleType(ImageView.ScaleType.CENTER_CROP);h.cover.setBackground(round(0xff1c1c1c,8));h.cover.setClipToOutline(true);row.addView(h.cover,new LinearLayout.LayoutParams(dp(56),dp(56)));LinearLayout labels=new LinearLayout(LibraryActivity.this);labels.setOrientation(LinearLayout.VERTICAL);labels.setPadding(dp(14),0,dp(8),0);h.title=text("",16,Color.WHITE);h.title.setSingleLine(true);h.title.setEllipsize(TextUtils.TruncateAt.END);h.subtitle=text("",12,0xff999999);h.subtitle.setSingleLine(true);h.subtitle.setEllipsize(TextUtils.TruncateAt.END);labels.addView(h.title);labels.addView(h.subtitle);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));h.more=button("⋮","Track options");h.more.setTextSize(24);h.more.setBackgroundColor(Color.TRANSPARENT);h.more.setFocusable(false);row.addView(h.more,new LinearLayout.LayoutParams(dp(48),dp(48)));row.setTag(h);}else{row=(LinearLayout)reused;h=(Holder)row.getTag();}LibraryStore.Track track=visible.get(position);h.uri=track.uri;h.title.setText(track.title);Meta info=metadata.get(track.uri);h.cover.setImageTintList(null);if(info!=null&&info.art!=null)h.cover.setImageBitmap(info.art);else{h.cover.setImageResource(R.drawable.ic_music);h.cover.setImageTintList(android.content.res.ColorStateList.valueOf(accent));}String detail=(track.video()?"Video":"Audio")+" • "+(track.downloaded()?"Downloaded":"Imported");if(info!=null){if(!info.artist.isEmpty())detail=info.artist+" • "+detail;if(info.duration>0)detail+=" • "+String.format(Locale.US,"%d:%02d",info.duration/60000,(info.duration/1000)%60);}h.subtitle.setText(detail);h.more.setOnClickListener(v->menu(v,track));if(info==null&&!pending.contains(track.uri)){pending.add(track.uri);readMetadata(track);}return row;}
 }
 void readMetadata(LibraryStore.Track track){worker.execute(()->{Meta value=new Meta();MediaMetadataRetriever r=new MediaMetadataRetriever();try{Uri uri=Uri.parse(track.uri);if(!"content".equals(uri.getScheme())&&!"file".equals(uri.getScheme()))return;r.setDataSource(this,uri);String artist=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ARTIST);if(artist!=null)value.artist=artist.substring(0,Math.min(artist.length(),200));String duration=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);if(duration!=null)try{value.duration=Long.parseLong(duration);}catch(NumberFormatException ignored){}byte[] bytes=r.getEmbeddedPicture();if(bytes!=null)value.art=Artwork.decode(bytes,256);else if(track.video()&&Build.VERSION.SDK_INT>=27)value.art=r.getScaledFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,160,160);}catch(Exception ignored){}finally{try{r.release();}catch(Exception ignored){}}runOnUiThread(()->{if(!closed){pending.remove(track.uri);metadata.put(track.uri,value);adapter.notifyDataSetChanged();}});});}
 protected void onDestroy(){closed=true;worker.shutdownNow();super.onDestroy();}
}
